// Source: src/code/search/feeds.js (+ src/lib/common.js). Edit there and run scripts/build.js.

// From config/profile.json
const CONFIG = {
  "candidate_profile": [
    "Candidate: entry-level (trainee / intern / junior), no commercial experience yet. Master's in Computer Science (graduating Dec 2026).",
    "Location: Lviv, Ukraine. Prefers remote, hybrid or an office in Lviv; an office in another city is fine for a good match.",
    "Main interests: no-code & AI automation (n8n, Apps Script, APIs),",
    "business, data or financial analysis, QA (manual first, test automation is fine too).",
    "Also open to adjacent trainee roles where the skills overlap: data engineering / BI, product design, analyst roles that use Python.",
    "Skills: SQL, Postman / REST APIs, Jira, Python (intermediate), Google Sheets & Apps Script, n8n, Telegram bots. English B2.",
    "Usually not a fit: roles for experienced specialists, software engineering as the main job, sales-only roles, customer support, night shifts."
  ],
  "feeds": {
    "dou_searches": [
      "trainee",
      "intern",
      "стажер",
      "junior",
      "business analyst",
      "technical analyst",
      "data analyst",
      "financial analyst",
      "manual qa",
      "qa engineer",
      "n8n",
      "automation specialist",
      "martech"
    ],
    "djinni_categories": [
      "",
      "Business Analyst",
      "QA",
      "Data Analyst",
      "Marketing"
    ]
  },
  "scoring": {
    "boost": [
      {
        "pattern": "trainee|intern|стажер|стажув|junior|джуніор|entry",
        "points": 4
      },
      {
        "pattern": "business analyst|\\bba\\b|technical analyst|data analyst|financial analyst|analyst|аналітик",
        "points": 3
      },
      {
        "pattern": "manual qa|\\bqa\\b|tester|тестувальник",
        "points": 2
      },
      {
        "pattern": "n8n|make\\.com|zapier|no-code|low-code|martech|automation|автоматизац",
        "points": 3
      },
      {
        "pattern": "\\bbi\\b|power bi|tableau|data engineer",
        "points": 2
      },
      {
        "pattern": "\\bsql\\b|postman|\\bjira\\b|python|\\bapi\\b",
        "points": 1
      }
    ],
    "penalty": [
      {
        "pattern": "senior|middle|сеньйор|principal|architect|director|head of",
        "points": -6
      },
      {
        "pattern": "\\blead\\b(?!\\s*gen)|team ?lead|тімлід",
        "points": -6
      },
      {
        "pattern": "developer|розробник|devops|data scientist|ml engineer|software engineer",
        "points": -8
      },
      {
        "pattern": "support|підтримк|night shift|sales manager|менеджер з продаж",
        "points": -3
      }
    ],
    "preferred_location": {
      "pattern": "львів|lviv|віддалено|remote",
      "points": 2
    }
  }
};

// ---------------------------------------------------------------------------
// Shared helpers. The build script prepends this file to every Code node,
// so each node stays self-contained inside n8n.
// ---------------------------------------------------------------------------

const TZ = 'Europe/Kyiv';

const SHEET = {
  MAIN: 'Вакансії',
  INBOX: 'Знайдені',
  HISTORY: 'Історія',
};

// Column names in the "Вакансії" sheet (must match the header row exactly)
const COL = {
  APPLIED: 'Дата відгуку',
  COMPANY: 'Компанія',
  POSITION: 'Позиція',
  LINK: 'Посилання',
  SOURCE: 'Джерело',
  FORMAT: 'Формат',
  LOCATION: 'Локація',
  SALARY: 'Зарплата',
  STAGE: 'Етап',
  STAGE_DATE: 'Етап змінено',
  NEXT: 'Наступний крок',
  NEXT_DATE: 'Дата наступного кроку',
  REASON: 'Причина відмови',
  CONTACT: 'Контакт',
  PRIORITY: 'Пріоритет',
  NOTES: 'Нотатки',
  AI_REASON: 'AI: причина',
  AI_GAPS: 'AI: чого бракувало',
  AI_ADVICE: 'AI: що підтягнути',
  AI_ACTION: 'AI: наступний крок',
};

// Column names in the "Знайдені" sheet
const IN = {
  FOUND: 'Знайдено',
  SCORE: 'Бал',
  COMPANY: 'Компанія',
  POSITION: 'Позиція',
  LOCATION: 'Локація',
  SALARY: 'Зарплата',
  SOURCE: 'Джерело',
  LINK: 'Посилання',
  STATUS: 'Статус',
  AI: 'AI-коментар',
};

const STAGES = [
  'Хочу відгукнутись', 'Відгукнулась', 'Контакт з рекрутером', "HR-інтерв'ю",
  'Тестове', "Технічне інтерв'ю", "Фінальне інтерв'ю", 'Офер',
  'Відмова', 'Відмовилась сама', 'Немає відповіді',
];
const CLOSED = ['Офер', 'Відмова', 'Відмовилась сама', 'Немає відповіді'];

const REASONS = [
  'Мало досвіду', 'Не пройшла тестове', 'Обрали іншого кандидата', 'Слабка англійська',
  'Не підійшла по софт-скілах', 'Вакансію закрили', 'Не зійшлись по зарплаті',
  'Без пояснень', 'Моє рішення', 'Інше',
];

// Short, stable id for a row or a link (used in Telegram button data)
function hash(s) {
  let h = 0;
  s = String(s);
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(36);
}

// Normalised link: no protocol, www, query, fragment or trailing slash
function urlKey(u) {
  return String(u || '').trim().split('#')[0].split('?')[0]
    .replace(/\/$/, '').replace(/^https?:\/\/(www\.)?/i, '').toLowerCase();
}

// Id of a vacancy row in the main sheet
function rowKey(r) {
  const k = urlKey(r[COL.LINK]);
  return hash(k || (String(r[COL.COMPANY] || '') + '|' + String(r[COL.POSITION] || '')));
}

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function short(s, n) {
  s = String(s == null ? '' : s);
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
}

// Date parts in Kyiv time
function kyivParts(d) {
  const f = new Intl.DateTimeFormat('en-GB', {
    timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false,
  });
  const p = {};
  for (const x of f.formatToParts(d || new Date())) p[x.type] = x.value;
  if (p.hour === '24') p.hour = '00';
  return p;
}

function todayISO(d) {
  const p = kyivParts(d);
  return `${p.year}-${p.month}-${p.day}`;
}

function nowStamp(d) {
  const p = kyivParts(d);
  return `${p.year}-${p.month}-${p.day} ${p.hour}:${p.minute}`;
}

function fmtDate(iso) {
  const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[3]}.${m[2]}.${m[1]}` : String(iso || '');
}

// Sheet dates arrive as "23.11.2026", "2026-11-23" or a serial number.
// Returns "YYYY-MM-DD" or "".
function parseDate(v) {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number') {
    const ms = Math.round((v - 25569) * 86400000);
    return new Date(ms).toISOString().slice(0, 10);
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{1,2})[./](\d{1,2})[./](\d{4})/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  return '';
}

// Whole days between two "YYYY-MM-DD" dates (b - a)
function daysBetween(a, b) {
  if (!a || !b) return null;
  return Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
}

function isClosed(stage) {
  return CLOSED.indexOf(stage) !== -1;
}

// One Telegram Bot API call, executed later by the "Telegram API" HTTP node
function tg(method, payload) {
  return { json: { kind: 'tg', method, payload } };
}

function chatId() {
  return String($env.TELEGRAM_CHAT_ID || '');
}

function sendText(text, extra) {
  return tg('sendMessage', Object.assign({
    chat_id: chatId(), text, parse_mode: 'HTML', disable_web_page_preview: true,
  }, extra || {}));
}

function rowsOf(nodeName) {
  try {
    return $(nodeName).all().map((i) => i.json).filter((r) => r && r.row_number);
  } catch (e) {
    return [];
  }
}

// Company name from a vacancy page: the JSON-LD "hiringOrganization" (Djinni, many
// career sites), otherwise the "Position в Company" title that DOU and Djinni use.
function companyFromPage(html) {
  html = String(html || '');
  const unq = (s) => s.replace(/\\u([0-9a-f]{4})/gi, (m, h) => String.fromCharCode(parseInt(h, 16))).replace(/\\"/g, '"');
  const ld = html.match(/"hiringOrganization"\s*:\s*\{[^{}]*?"name"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (ld && ld[1].trim()) return unq(ld[1]).trim();
  const t = html.match(/<meta[^>]*property="og:title"[^>]*content="([^"]*)"/i) || html.match(/<title[^>]*>([^<]*)</i);
  if (!t) return '';
  const title = t[1].replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/\s*[|–—-]\s*(Djinni|DOU)\s*$/i, '').trim();
  const i = title.lastIndexOf(' в ');
  return i > 0 ? title.slice(i + 3).split(',')[0].trim() : '';
}

// ---------------------------------------------------------------------------

// Builds the list of RSS feeds to check. One output item = one HTTP request.

// Search terms and categories come from config/profile.json
const DOU_SEARCHES = CONFIG.feeds.dou_searches;
// Djinni: "no experience" feed, plus a few categories ('' = all categories)
const DJINNI_CATEGORIES = CONFIG.feeds.djinni_categories;

const out = [];
for (const q of DOU_SEARCHES) {
  out.push({ json: {
    source: 'DOU',
    url: 'https://jobs.dou.ua/vacancies/feeds/?exp=0-1&search=' + encodeURIComponent(q),
  } });
}
for (const c of DJINNI_CATEGORIES) {
  out.push({ json: {
    source: 'Djinni',
    url: 'https://djinni.co/jobs/rss/?exp_level=no_exp' + (c ? '&primary_keyword=' + encodeURIComponent(c) : ''),
  } });
}
return out;

